using System.Text;

namespace Klangkiste
{
    public static class HilfeInhalte
    {
        public static IReadOnlyList<HilfeThema> ErzeugeThemen()
        {
            return new[]
            {
                                new HilfeThema("1. Erste Schritte", "Die Klangkiste verwaltet Verweise auf Mediendateien. Wählen Sie zunächst „Ordner einlesen“, fügen Sie einen oder mehrere Ordner hinzu und entscheiden Sie, ob Unterordner berücksichtigt werden sollen. Über „Exportieren“ bzw. „Sammlung speichern“ legen Sie die Sammlung als .mcd-Datei ab; „Importieren“ lädt eine vorhandene .mcd wieder."),
                new HilfeThema("2. Ordner einlesen", "Der Dialog „Ordner einlesen“ enthält einen kleinen Ordner-Browser: Oben wählen Sie ein Laufwerk und können den Pfad auch direkt eintippen (Enter zum Springen). In der Mitte sehen Sie die Unterordner des aktuellen Ordners – Doppelklick öffnet einen Ordner, „Hoch“ bzw. der Eintrag „..“ geht eine Ebene zurück. Über „Diese Ebene →“ den aktuellen Ordner bzw. über „Markierte →“ mehrere markierte Unterordner zur Liste „Zum Einlesen vorgemerkte Ordner“ hinzufügen (mit „Entfernen“ wieder herausnehmen). Jeder vorgemerkte Ordner wird als eigener Stammordner eingelesen. „Unterordner einbeziehen“ gilt für alle; bereits in der Sammlung vorhandene Ordner werden beim Hinzufügen übersprungen (außer Sie haken „Bereits eingelesene Ordner trotzdem zulassen“ an). Über „Als Hauptlaufwerk“ legen Sie den aktuellen Ordner als Startordner fest, in dem der Browser künftig immer öffnet. Nicht erreichbare Dateien werden übersprungen; die Sammlung speichert nur Verweise und ausgelesene Metadaten. Nach dem Einlesen gilt die Sammlung stets als geändert."),
                new HilfeThema("3. Dateifilter", "Neben Audio, Video, Audio und Video sowie allen Dateitypen können eigene Filter verwendet werden. Mehrere Muster werden mit Semikolon getrennt, zum Beispiel *.mp3;*.flac oder .cue;.m3u. *.* berücksichtigt alle Dateien."),
                new HilfeThema("4. Unterstützte Dateiformate", ErzeugeFormatInhalt()),
                new HilfeThema("5. Dateiliste und Metadaten", "Die Dateiliste kann Dateiname, Titel, Interpret, Album, Jahr, Bitrate, Größe, Dauer, Pfad, Änderungsdatum und Medientyp anzeigen. Sichtbarkeit, Reihenfolge und Breite der Spalten können angepasst werden. Ein Klick auf eine Spaltenüberschrift sortiert die Liste; ein erneuter Klick kehrt die Reihenfolge um."),
                new HilfeThema("6. Größen- und Zeitangaben", "Dateigrößen werden automatisch in Bytes, KB, MB, GB oder TB mit maximal zwei Nachkommastellen angezeigt. Die Dauer verwendet das Format Stunden:Minuten:Sekunden. Bitraten werden in kbps dargestellt."),
                new HilfeThema("7. Sortierung der Ordnerliste", "Der Button „Ordner sortieren“ sortiert die komplette Ordnerstruktur rekursiv neu – auf jeder Ebene werden zunächst Sonderzeichen, dann Zahlen und dann Buchstaben berücksichtigt. Die Sortierung wird vor dem Start abgefragt. Der Button ist aktiv, sobald sich mindestens ein Ordner in der Sammlung befindet. Nach dem Sortieren gilt die Sammlung als geändert. Auch die Dateiliste sortiert nach dieser Reihenfolge (Sonderzeichen, Zahlen, Buchstaben), sobald Sie eine Spaltenüberschrift anklicken."),
                new HilfeThema("8. Auswahlmodi", "Der normale Modus verwendet die übliche Strg-/Shift-Auswahl. Im Kontrollkästchen-Modus wird über Kontrollkästchen ausgewählt. Der Hybrid-Modus kombiniert beide Möglichkeiten. Ordnerübergreifende Auswahl kann aktiviert werden."),
                new HilfeThema("9. Wiedergabe", "Audio- und Videodateien können über getrennte Playerprofile wiedergegeben werden. Möglich sind Windows-Standardanwendung, VLC, Winamp, foobar2000 oder eine eigene EXE-Datei. Je Profil lässt sich festlegen, wie die Dateien übergeben werden (Playlist, Dateien direkt oder Einzeldatei). Das Argument-Template unterstützt die Platzhalter {playlist} (temporäre M3U), {file} (alle Dateien) und {first} (erste Datei)."),
                new HilfeThema("10. .mcd-Sammlungen", "Eine .mcd-Datei enthält keine Mediendateien, sondern Verweise und Metadaten. Beim Export werden Pfade relativ zum Speicherort der .mcd gespeichert. Absolute ältere Pfade bleiben beim Import kompatibel. Verschobene oder gelöschte Dateien müssen neu verknüpft bzw. erneut eingelesen werden. Beim Start wird die zuletzt geladene Sammlung automatisch geöffnet. Der Button „Neue Sammlung“ schließt die aktuelle Sammlung und leert die Ordnerliste – die zuletzt geladene .mcd-DATEI bleibt dabei auf dem Datenträger erhalten; nur der Verweis darauf wird aus der config.ini entfernt. Bestehen ungespeicherte Änderungen, wird vorher gefragt, ob gespeichert werden soll."),
                new HilfeThema("11. Einstellungen", "In den Einstellungen können Player, Auswahlmodus, ordnerübergreifende Auswahl, Gitternetz, Dateispalten sowie Schriftart und -größe konfiguriert werden. Die Einstellungen werden in config.ini gespeichert."),
                new HilfeThema("12. Designs", "Die Darstellung kann hell, dunkel oder automatisch (abhängig vom Windows-App-Design) sein. Toolbar, Statusleiste, Buttons, Dateiliste, Auswahlmarkierung und Gitternetz verwenden die Werte des aktiven Designs. Schriftart und Schriftgröße werden im Einstellungsfenster gewählt. Die Anordnung – auch die Breite der Trennung zwischen Ordnerliste und Dateiliste – wird gespeichert und beim nächsten Start wiederhergestellt."),
                new HilfeThema("13. Fehlerbehebung", "Bei fehlenden Dateien, nicht erreichbaren Ordnern, fehlenden Metadaten oder nicht gefundenen Playern werden die Dateien beziehungsweise Aktionen übersprungen oder eine Meldung angezeigt. Für Konfigurationsdateien werden bei fehlenden Schreibrechten Ausweichpfade verwendet."),
                new HilfeThema("14. Toolbar und Statusleiste", "Die Toolbar enthält links „Ordner einlesen“, „Neue Sammlung“, „Importieren“, „Exportieren“, „Sammlung speichern“ und „Ordner sortieren“, rechts „Einstellungen“ und „Hilfe“. „Sammlung speichern“ und „Neue Sammlung“ sind nur aktiv, wenn eine .mcd geladen ist. „Ordner sortieren“ ist aktiv, sobald mindestens ein Ordner in der Sammlung vorhanden ist. Die Statusleiste zeigt die Anzahl der Ordner und Dateien sowie – bei aktivem Filter oder Gesamtsuche – die Anzahl der Treffer an."),
                new HilfeThema("15. Suche und Filter", "Über die Filterzeile lässt sich die angezeigte Dateiliste nach Dateiname, Titel, Artist und Album einschränken. Jedes Feld kann einzeln oder kombiniert genutzt werden; leere Felder werden ignoriert, mehrere Felder werden UND-verknüpft. Ohne Sonderzeichen wird nach „enthält“ gesucht (unabhängig von Groß-/Kleinschreibung). Mit * steht für beliebig viele Zeichen und ? für genau ein Zeichen, zum Beispiel test* (beginnt mit test), *.mp3 (alle MP3) oder *live* (enthält live). Mit „Ganze Sammlung durchsuchen“ werden alle Ordner einbezogen. Über „Filter löschen“ werden alle Felder geleert. Die Suche verändert die Sammlung nicht, sondern blendet nur Einträge aus."),
                new HilfeThema("16. Dateirechte / Zugriff verweigert", "Beim Löschen vom Medium kann die Meldung „Zugriff verweigert“ erscheinen. Die Ursache sind dann fehlende Windows-Dateirechte (ACL) für Ihr Benutzerkonto bzw. Ihre Gruppe, nicht ein Fehler der Klangkiste. Häufig stammen solche Dateien von anderen Systemen, Datenträgern oder Sicherungen, bei denen die „Benutzer“-Gruppe nur „Lesen und Ausführen“ besitzt – Löschen ist dann gesperrt.\n\nEin Programm kann sich diese Rechte nicht selbst geben; auch ein normaler Start der Klangkiste läuft nicht mit erhöhten Rechten. So beheben Sie es in Windows:\n1. Im Explorer die Datei bzw. den Ordner mit Rechtsklick → „Eigenschaften“ öffnen.\n2. Reiter „Sicherheit“ → Schaltfläche „Erweitert“.\n3. Beim „Besitzer“ auf „Ändern“ und Ihren Benutzer als Besitzer übernehmen (ggf. „Besitz von Untercontainern und Objekten übernehmen“ anhaken).\n4. Unter „Berechtigungen“ Ihrem Konto „Vollzugriff“ erteilen.\n5. Die Änderung übernehmen.\n\nGehört das Konto nicht zu den Administratoren, kann nur jemand mit entsprechenden Rechten (Administrator, IT oder Eigentümer) die Rechte einmalig setzen. Danach funktioniert das Löschen auch in der Klangkiste.")
            };
        }

        private static string ErzeugeFormatInhalt()
        {
            var text = new StringBuilder("Standardmäßig werden folgende Formate erkannt:\n\n");
            foreach (Medienformat format in MedienformatDefinition.Alle)
            {
                text.AppendLine($"{format.Endung} – {format.Format} ({format.Kategorie})");
                text.AppendLine($"  {format.MetadatenHinweis}");
            }

            text.Append("\nDie Erkennung der Dateiendungen ist unabhängig von Groß- und Kleinschreibung. Containerformate können unterschiedliche Codecs enthalten; die Abspielbarkeit hängt vom verwendeten Player ab.");
            return text.ToString();
        }
    }
}
